INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch10$PT156-S4-Q6$batch10$, 156, 4, 6, $batch10$Role$batch10$, $batch10$Anthropologist: During the last ice age, nomadic communities probably needed at least 15 or 20 members to survive, and they were generally not much larger than this. Ice-age nomads are commonly portrayed as primarily big-game hunters, but most of their food must have in fact come from other sources, such as small game and plants. Hunting large animals is a dangerous activity that would have risked the lives of several members of the community.$batch10$, $batch10$Which one of the following most accurately describes the role played in the argumentation by the statement that ice-age nomads are commonly portrayed as primarily big-game hunters?$batch10$, $batch10$E$batch10$, true, $batch10$Batch 10; question text from local bank.$batch10$ FROM lr_sections s WHERE s.preptest=156 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT156-S4-Q6$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$A$batch10$, $batch10$It is a premise used as support for the overall conclusion of the anthropologist’s argument.$batch10$, $batch10$Wrong Role$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT156-S4-Q6$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$A$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$B$batch10$, $batch10$It is a clarification of one of the premises of the anthropologist’s argument.$batch10$, $batch10$Wrong Role$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT156-S4-Q6$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$B$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$C$batch10$, $batch10$It is an objection that the anthropologist raises against an opposing theory.$batch10$, $batch10$Wrong Role$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT156-S4-Q6$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$C$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$D$batch10$, $batch10$It is the overall conclusion of the anthropologist’s argument.$batch10$, $batch10$Wrong Role$batch10$, false FROM lr_questions q WHERE q.qid=$batch10$PT156-S4-Q6$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$D$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch10$E$batch10$, $batch10$It describes a claim that the anthropologist attempts to refute.$batch10$, $batch10$Correct$batch10$, true FROM lr_questions q WHERE q.qid=$batch10$PT156-S4-Q6$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch10$E$batch10$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT156-S4-Q6$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Opposing Point$batch10$, $batch10$Ice-age nomads are commonly portrayed as mainly big-game hunters.$batch10$), (1, $batch10$Conclusion$batch10$, $batch10$Most of their food must have come from other sources, such as small game and plants.$batch10$), (2, $batch10$Evidence$batch10$, $batch10$Communities had only about 15 to 20 members, about the minimum needed to survive. Hunting large animals is dangerous and would risk the lives of several members.$batch10$), (3, $batch10$Evaluate$batch10$, $batch10$The statement in question is introduced as a common portrayal, and "but" turns against it. The anthropologist's conclusion is the opposite view. So the statement describes a claim the anthropologist is trying to refute.$batch10$), (4, $batch10$Goal$batch10$, $batch10$The statement describes a view the anthropologist argues against.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT156-S4-Q6$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$The portrayal doesn't support the conclusion. The conclusion contradicts it.$batch10$), ($batch10$B$batch10$, $batch10$It doesn't clarify a premise. It's the view the premises are used against.$batch10$), ($batch10$C$batch10$, $batch10$It isn't the anthropologist's objection. It's the theory the anthropologist objects to.$batch10$), ($batch10$D$batch10$, $batch10$The conclusion is that nomads mostly ate other foods. The portrayal is what that conclusion rejects.$batch10$), ($batch10$E$batch10$, $batch10$"Commonly portrayed as" sets up a popular view, and "but" rejects it. The anthropologist is trying to refute it.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT156-S4-Q6$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
